package com.wizzadrds.theworldremembers.behavior;
import net.minecraft.server.MinecraftServer; import net.minecraft.server.level.ServerLevel; import net.minecraft.world.level.saveddata.*; import net.minecraft.resources.Identifier; import com.mojang.serialization.Codec; import java.util.*;
public final class NpcBehaviorManager extends SavedData { private final Map<UUID,NpcBehaviorState> states=new HashMap<>(); private static final Codec<NpcBehaviorManager> CODEC=Codec.unboundedMap(Codec.STRING.xmap(UUID::fromString,UUID::toString),NpcBehaviorState.CODEC).xmap(m->{var x=new NpcBehaviorManager();x.states.putAll(m);return x;},x->x.states); private static final SavedDataType<NpcBehaviorManager> TYPE=new SavedDataType<>(Identifier.fromNamespaceAndPath("the_world_remembers","behavior"),NpcBehaviorManager::new,CODEC,null); public static NpcBehaviorManager get(MinecraftServer s){ServerLevel l=s.getLevel(ServerLevel.OVERWORLD);return l==null?new NpcBehaviorManager():l.getDataStorage().computeIfAbsent(TYPE);} public NpcBehaviorState get(UUID id){return states.get(id);} public void observe(UUID id,NpcActivity a,net.minecraft.core.BlockPos target,long tick,int fatigue){states.put(id,new NpcBehaviorState(a,target,tick,fatigue));setDirty();} }
